namespace {bool watch=false;uint64_t allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}class Original:public H8SEmulator{public:void histories(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t clocks;unsigned at;uint8_t value;bool write;};
template<class D>struct Tape{D&d;bool overlay=false,recording=false,context=false,trampoline=false;unsigned count=0,lcdBusy=2,phasePc=0,scan=0;std::array<uint16_t,32>words{};std::array<Event,16>events{};explicit Tape(D&s):d(s){}void record(unsigned a,uint8_t v,bool w){if(!recording||!w&&a>=phasePc&&a<phasePc+12||context&&a>=0xfffea0&&a<0xffff10||trampoline&&!w&&a>=0xfffd10&&a<0xfffd1c)return;check(count<events.size(),"Tape overflow");events[count++]={d.cycles,a,v,w};}uint8_t read(unsigned a){auto v=d.memory[a<0x10000&&overlay?0x400000+a:a];if(a==0xffffc7){auto select=d.memory[0xffffd3];if(select==0x10)v=uint8_t(words[scan<32?scan:31]);else if(select==0x18){v=uint8_t(words[scan<32?scan:31]>>8);++scan;}else v=lcdBusy?(--lcdBusy,0x80):0;}record(a,v,false);return v;}void write(unsigned a,uint8_t v){record(a,v,true);d.memory[a]=v;if(a==0xffffcf)overlay=!(v&1);}};
struct OldBus:H8SDevice{Tape<Original>&t;explicit OldBus(Tape<Original>&s):t(s){}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct NewBus:kstation::ControllerResourceBus{Tape<kstation::ControllerDeviceState>&t;explicit NewBus(Tape<kstation::ControllerDeviceState>&s):t(s){}bool mapped(unsigned a)const override{return a<0x10000||a>=0x200000&&a<0x240000||a>=0x400000&&a<0x420000||a>=0xfffd00;}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct Fixture{using R=kstation::ControllerStartupButtonsRuntime;std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::ControllerDeviceState>d=std::make_unique<kstation::ControllerDeviceState>();Tape<Original>x{*a};Tape<kstation::ControllerDeviceState>y{*d};OldBus xb{x};NewBus yb{y};R native;kstation::ControllerLcdRuntime lcd;kstation::ControllerInterruptRuntime irq;uint64_t phases=0,io=0,shorts=0;unsigned scenario=0;void byte(unsigned at,unsigned v){a->memory[at]=d->memory[at]=uint8_t(v);}void wide(unsigned at,unsigned v){for(unsigned i=0;i<4;++i)byte(at+i,v>>(8*(3-i)));}
Fixture(const std::vector<uint8_t>&rom,unsigned flags,unsigned test):scenario(test){a->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);for(auto p:{std::pair{0,0x10000},std::pair{0xfffd00,0x300}})a->memmap(&xb,p.first,p.second);d->attachBus(&yb);irq.setMask(kstation::ControllerInterruptRuntime::Mask::Disabled);check(native.bindBootResources(*d,rom.data(),rom.size()),"Probe bind");check(lcd.bindBootResources(*d,rom.data(),rom.size()),"LCD bind");a->pc=a->makepc(0xf46);a->setSP(0xffff00);wide(0xffff00,0x3ae8);a->ccr=uint8_t(flags|128);a->histories(-1,-1);a->cycles=d->cycles=flags==255?~uint64_t(0)-7:100000;x.words.fill(0xffff);y.words.fill(0xffff);auto set=[&](std::initializer_list<unsigned>words){unsigned i=0;for(auto v:words)x.words[i]=y.words[i]=uint16_t(v),++i;};if(test==1)set({0xff8f,0xff8f});if(test==2)set({0x8fff,0x8fff,0xffff,0xffff,0xfdff,0xfdff,0xffff,0xffff,0xfdff,0xfdff});if(test==3)set({0x8fff,0x8fff,0xffff,0xffff,0xfdfe,0xfdfe});if(test==4)set({0x8fff,0x8fff,0xffff,0xffff,0xfdff,0xfdff,0xffff,0xffff,0xfdfe,0xfdfe});if(test==5)set({0xfffe,0xffff,0xffff,0xffff});check(native.start(),"Probe start");x.recording=y.recording=true;}
void equal(unsigned pc){if(a->cycles!=d->cycles){std::fprintf(stderr,"PC%x clocks%llu/%llu\n",pc,a->cycles,d->cycles);throw std::runtime_error("Probe clocks");}if(x.count!=y.count){std::fprintf(stderr,"PC%x IO%u/%u\n",pc,x.count,y.count);throw std::runtime_error("Probe IO count");}for(unsigned i=0;i<x.count;++i){auto&p=x.events[i];auto&q=y.events[i];if(!(p.clocks==q.clocks&&p.at==q.at&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"PC%x IO%u addr%x/%x value%x/%x time%llu/%llu\n",pc,i,p.at,q.at,p.value,q.value,p.clocks,q.clocks);throw std::runtime_error("Probe ordered IO");}}io+=x.count;}
void run(){for(unsigned i=0;native.active()&&i<1200000;++i){if(native.request()!=R::Request::None){check(scenario==1&&a->getPC()==0xf7c,"Probe update request");return;}auto pc=unsigned(a->getPC());x.context=y.context=true;x.phasePc=y.phasePc=pc&0xffffff;x.count=y.count=0;auto n=native.nextClocks(*d,irq,lcd);if(i<100||i%701==0){auto snapshot=native;auto cycle=d->cycles;int read=d->lastRead,write=d->lastWrite;for(unsigned b=0;b<n;++b){check(!native.advanceBefore(*d,irq,lcd,b).clocks,"Probe short accepted");check(!std::memcmp(&snapshot,&native,sizeof(native))&&cycle==d->cycles&&read==d->lastRead&&write==d->lastWrite&&!x.count&&!y.count,"Probe short mutated");++shorts;}}auto r=native.advanceBefore(*d,irq,lcd,n);check(r.clocks,"Probe refused");a->step();equal(pc);++phases;}check(!native.active()&&a->getPC()==0x3ae8,"Probe runaway");check(a->memory[0xfffe3d]==(scenario==2?0xaa:0),"Probe marker");for(auto p:{std::pair{0xfffd10,0x190},std::pair{0xffff10,0xf0}})check(!std::memcmp(a->memory+p.first,d->memory+p.first,p.second),"Probe memory differs");}
};}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n))return p;throw std::bad_alloc();}void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};unsigned cases=0;uint64_t phases=0,io=0,shorts=0;for(unsigned test=0;test<6;++test)for(unsigned flags:{0u,127u,255u}){Fixture f(rom,flags,test);watch=true;f.run();watch=false;phases+=f.phases;io+=f.io;shorts+=f.shorts;++cases;}check(!allocations,"Processing allocation");std::printf("{\"passed\":true,\"cases\":%u,\"native_phases\":%llu,\"ordered_io\":%llu,\"short_budgets\":%llu,\"processing_allocations\":%llu,\"update_wrapper_f7c_closed\":false}\n",cases,phases,io,shorts,allocations);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
